/**
 * Main workflow — "Validate Row" Code node
 * ----------------------------------------------------------------------------
 * Input  : one item from the Google Sheets Trigger (one new Form response row).
 *          The row's keys are exactly the column headers from row 1 of the sheet.
 * Output : { ok: boolean, row: <original>, errors: string[] }
 *
 * Checks:
 *   1. Email is present and shaped like an email address.
 *   2. Name is present.
 *   3. Fulfillment Date is present and parseable.
 *   4. Fulfillment Type is "Pickup" or "Delivery".
 *   5. If Delivery, Delivery Address is non-empty.
 *   6. At least one SKU quantity column is > 0.
 *
 * IMPORTANT: This Code node does NOT hard-code the SKU column names.
 * Everything that is not in the META set below is treated as a candidate
 * SKU column. To add a menu item to the Form, you add a column to the sheet
 * AND a row to `item_config` — you do NOT edit this Code node.
 */
const row = $input.item.json;
const errors = [];

const email = String(row['Email'] ?? row['Email Address'] ?? '').trim();
if (!email) {
  errors.push('email is missing');
} else if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) {
  errors.push('email format looks wrong');
}

const name = String(row['Name'] ?? '').trim();
if (!name) errors.push('name is missing');

const fulfillmentDate = String(row['Fulfillment Date'] ?? '').trim();
if (!fulfillmentDate) {
  errors.push('fulfillment date is missing');
} else if (Number.isNaN(Date.parse(fulfillmentDate))) {
  errors.push('fulfillment date is not a valid date');
}

const fulfillmentType = String(row['Fulfillment Type'] ?? '').trim();
if (!['Pickup', 'Delivery'].includes(fulfillmentType)) {
  errors.push('fulfillment type must be "Pickup" or "Delivery"');
}

const address = String(row['Delivery Address'] ?? '').trim();
if (fulfillmentType === 'Delivery' && !address) {
  errors.push('delivery address is required for Delivery orders');
}

// META = column headers we treat as customer / order metadata, NOT SKU quantities.
// Adding a new SKU column to the sheet does not require editing this set.
const META = new Set([
  'Timestamp',
  'Email', 'Email Address',
  'Name',
  'Contact Number', 'Phone',
  'Fulfillment Date',
  'Fulfillment Type',
  'Delivery Address',
  'Payment Method',
  'Special Instructions',
  'row_number',                    // injected by the Google Sheets Trigger
  'Invoice ID', 'Sync Status',     // write-back columns (round-tripped after sync)
]);

let totalQty = 0;
for (const [k, v] of Object.entries(row)) {
  if (META.has(k)) continue;
  const n = Number(v);
  if (Number.isFinite(n) && n > 0) totalQty += n;
}
if (totalQty <= 0) errors.push('no item quantities greater than zero');

return [{ json: { ok: errors.length === 0, row, errors } }];

/**
 * Main workflow — "Normalize Order" Code node
 * ----------------------------------------------------------------------------
 * Converts the validated sheet row into the NORMALIZED ORDER payload that
 * the "Order → Invoice" sub-workflow accepts. This is the boundary contract
 * shared between the Google Sheet intake (today) and the future Supabase
 * form intake — both produce this same shape.
 *
 * Normalized order shape:
 * {
 *   source: 'google_sheet' | 'supabase_form',
 *   source_row_id: '<source-prefix>:<stable-id>',
 *   customer: { email, name, phone },
 *   fulfillment: { date, type, address },
 *   payment_method, special_instructions,
 *   item_quantities: { '<sheet_column_header>': <number> },
 *   writeback: { kind, ...intake-specific }
 * }
 */
const crypto = require('crypto');
const row = $input.item.json.row;

const email = String(row['Email'] ?? row['Email Address'] ?? '').trim().toLowerCase();
const timestamp = String(row['Timestamp'] ?? '').trim();

// Stable id: hash of (timestamp + email). Survives row reorders / re-runs.
const idHash = crypto
  .createHash('sha256')
  .update(timestamp + '|' + email)
  .digest('hex')
  .slice(0, 16);

const META = new Set([
  'Timestamp',
  'Email', 'Email Address',
  'Name',
  'Contact Number', 'Phone',
  'Fulfillment Date',
  'Fulfillment Type',
  'Delivery Address',
  'Payment Method',
  'Special Instructions',
  'row_number',
  'Invoice ID', 'Sync Status',
]);

const item_quantities = {};
for (const [k, v] of Object.entries(row)) {
  if (META.has(k)) continue;
  const n = Number(v);
  if (Number.isFinite(n) && n > 0) item_quantities[k] = n;
}

const address = String(row['Delivery Address'] ?? '').trim();

const payload = {
  source: 'google_sheet',
  source_row_id: `gs:${idHash}`,
  customer: {
    email,
    name: String(row['Name'] ?? '').trim(),
    phone: String(row['Contact Number'] ?? row['Phone'] ?? '').trim(),
  },
  fulfillment: {
    date: String(row['Fulfillment Date'] ?? '').trim(),
    type: String(row['Fulfillment Type'] ?? '').trim(),
    address: address || null,
  },
  payment_method: String(row['Payment Method'] ?? '').trim(),
  special_instructions: String(row['Special Instructions'] ?? '').trim(),
  item_quantities,
  writeback: {
    kind: 'google_sheet',
    spreadsheet_id: $vars.GS_SPREADSHEET_ID,
    sheet_name: $vars.GS_RESPONSES_SHEET,
    row_number: row.row_number ?? null,
  },
};

return [{ json: payload }];

/**
 * Main workflow — "Build Notify Payload" Code node (validation-failure path)
 * ----------------------------------------------------------------------------
 * When "Validate Row" finds problems, we hand the Notify sub-workflow a
 * compact, channel-agnostic payload. The Notify workflow decides whether
 * to format it as Slack text or email body.
 */
const v = $input.item.json;
return [{
  json: {
    severity: 'error',
    stage: 'sheet-intake-validation',
    source: 'google_sheet',
    errors: v.errors || ['unknown validation failure'],
    row: v.row,
  },
}];
